"""Launch runs on Kaggle from your own machine with the Kaggle CLI.

    python scripts/kaggle_push.py full_ft --smoke   # one run: RTE 1k seed 1
    python scripts/kaggle_push.py full_ft           # all 16 runs (run_method.sh)
    python scripts/kaggle_push.py --extra lr        # LR search (run_extra.sh)
    python scripts/kaggle_push.py --extra ablation  # ablations (run_extra.sh)

Needs the Kaggle CLI and ~/.kaggle/kaggle.json (kaggle.com/settings -> API).
The repo is private, so instead of cloning from GitHub on Kaggle, this packs
the repo files (everything git tracks or would track, including
results/final/*.json, so finished runs are skipped) into a Kaggle script and
pushes it. If there are uncommitted changes, the results get git_commit
"<hash>-dirty", so commit before the real runs.

Afterwards:
    kaggle kernels status <user>/<slug>
    kaggle kernels output <user>/<slug> -p <dir>
"""  # DOCSTRING: description of this whole file, also shown by --help. This file's job: start training runs on Kaggle's free GPU directly from your laptop. Because the GitHub repo is private, it packs the code into the Kaggle script itself instead of cloning from GitHub.

from __future__ import annotations  # Makes Python treat type hints as plain text, so modern hint syntax works on older Python versions. Does not change how the code runs.

import argparse  # Standard library for reading command-line options (method name, --extra, --smoke, --no-push).
import base64  # Standard library to convert binary data (the .tar.gz archive) into plain text characters, so it can be pasted inside a Python file as a string.
import io  # Standard library for in-memory files: io.BytesIO lets us build the .tar.gz in RAM, without writing a temporary file to disk.
import json  # Standard library for JSON: writes kernel-metadata.json and reads your Kaggle username from kaggle.json.
import subprocess  # Standard library to run other programs: git (to list files and get the commit hash) and the kaggle command-line tool (to upload).
import sys  # Standard library; used here to print the warning about uncommitted changes to stderr (the error stream), so it stands out from normal output.
import tarfile  # Standard library to create .tar.gz archives (many files packed and compressed into one).
import tempfile  # Standard library to create a temporary folder where run.py and kernel-metadata.json are written before uploading.
from pathlib import Path  # Object-style file paths that work on both Windows and Linux.

REPO = Path(__file__).resolve().parent.parent  # Absolute path of the project folder. This file is scripts/kaggle_push.py: .parent = scripts/, .parent again = repo root. Correct no matter which folder you run the script from.
METHODS = ("full_ft", "lora", "adapter", "prompt_tuning")  # The 4 valid method names; used as argparse choices so a typo is rejected immediately.

KERNEL_TEMPLATE = r'''
# Generated by scripts/kaggle_push.py from commit {commit}. Do not edit here.
import base64, io, os, subprocess, sys, tarfile  # Libraries the Kaggle script needs: to decode the packed code, unpack it, and run shell commands.

CODE = "{code}"  # The WHOLE repo as one long base64 text, inserted here by main(). This is how the code gets to Kaggle without GitHub access.
COMMIT = "{commit}"  # The git hash of the uploaded code, inserted by main(). Passed on so every result records which code version made it.
CMDS = {cmds!r}  # The list of shell commands to run, inserted by main(), e.g. bash scripts/run_method.sh lora.

root = "/kaggle/working/peft-showdown"  # Folder on Kaggle where the repo is unpacked. Files under /kaggle/working are kept as the notebook OUTPUT, so the result JSONs can be downloaded afterwards.
os.makedirs(root, exist_ok=True)  # Create that folder; exist_ok=True means no error if it already exists.
tarfile.open(fileobj=io.BytesIO(base64.b64decode(CODE)), mode="r:gz").extractall(root)  # Decode the base64 text back into the .tar.gz bytes, open it from memory, and unpack every repo file into root.
os.chdir(root)  # Move into the repo folder. Required because python -m src.train only finds the src package when run from the repo root.
env = dict(os.environ, PEFT_GIT_COMMIT=COMMIT, PYTHONUNBUFFERED="1")  # Environment for the commands: PEFT_GIT_COMMIT lets results.py record the commit (there is no .git folder on Kaggle); PYTHONUNBUFFERED makes print output appear in the log immediately, not in delayed chunks.

def sh(cmd):  # Helper that runs one shell command and returns its exit code (0 = success).
    print("\n$ " + cmd, flush=True)  # Print the command first, so the log shows what is running.
    return subprocess.run(cmd, shell=True, env=env).returncode  # Run it through the shell with the environment above and return the exit code.

sh("nvidia-smi --query-gpu=name,memory.total --format=csv")  # Print which GPU Kaggle gave us and its memory, to confirm it is a Tesla T4.
if sh("pip install -q -r requirements.txt") != 0:  # Install the exact library versions pinned in requirements.txt; -q keeps the log short.
    sys.exit("pip install failed")  # If installation failed, stop now: every training run would fail anyway without the libraries.
# Kaggle ships torchao 0.10; peft 0.21 refuses to build LoRA / prompt tuning
# when an old torchao is installed. We don't use torchao, so remove it.
sh("pip uninstall -y -q torchao")  # Remove torchao. Without this, LoRA and prompt tuning crash on Kaggle when the model is built.
sh("python -c \"import torch, transformers, peft, adapters; "  # Quick sanity check: import all main libraries in a fresh Python ...
   "print('torch', torch.__version__, 'cuda', torch.cuda.is_available(), "  # ... print the torch version and whether the GPU is visible ...
   "'transformers', transformers.__version__, 'peft', peft.__version__, "  # ... the transformers and peft versions ...
   "'adapters', adapters.__version__)\"")  # ... and the adapters version. If any import fails, you see it here at the top of the log.
code = 0  # Overall exit code of the whole job; 0 means everything succeeded.
for c in CMDS:  # Run each requested command in order ...
    code = sh(c) or code  # ... if a command fails (non-zero), keep its code; a later success never hides an earlier failure.
print("\nexit code", code)  # Print the final status at the end of the log, so you can see at a glance whether anything failed.
'''  # KERNEL_TEMPLATE: the text of the Python script that will run ON KAGGLE. It is a template: main() fills in the three placeholders (code, commit, cmds) using .format(). Because of .format(), the comments inside it must never contain curly braces.


def git(*args: str) -> str:  # HELPER git: runs a git command inside the repo and returns what it prints, e.g. git("rev-parse", "--short", "HEAD") -> "bec25ec". *args collects any number of words.
    return subprocess.run(["git", *args], cwd=REPO, check=True,  # Run "git <args>" with the repo as working folder (so it works from anywhere). check=True raises an error if git fails, instead of silently continuing with wrong data.
                          capture_output=True, text=True).stdout.strip()  # Capture the output instead of printing it, as text (not bytes), and remove the trailing newline.


def kaggle_username() -> str:  # HELPER kaggle_username: returns your Kaggle username, which is part of the kernel id (username/kernel-name).
    cfg = Path.home() / ".kaggle" / "kaggle.json"  # The Kaggle API token file in your home folder (downloaded from kaggle.com -> Settings -> API). It contains your username and API key.
    return json.loads(cfg.read_text())["username"]  # Read the file, parse the JSON and return the "username" field. If the file is missing you get an error: set up the Kaggle API token first.


def main() -> None:  # FUNCTION main: the whole job. 1) read options, 2) get the commit hash, 3) pack the repo into base64 text, 4) choose the commands and kernel name, 5) write run.py + kernel-metadata.json, 6) upload with "kaggle kernels push".
    p = argparse.ArgumentParser(description=__doc__,  # Create the command-line parser; --help shows this file's docstring ...
                                formatter_class=argparse.RawDescriptionHelpFormatter)  # ... keeping its line breaks and indentation.
    p.add_argument("method", nargs="?", choices=METHODS)  # Positional option: which method to run (e.g. "lora"). nargs="?" makes it optional, because with --extra no method is needed.
    p.add_argument("--extra", choices=("lr", "ablation", "check"),  # Instead of one method, run the extra experiments: "lr" = LR search (16 runs), "ablation" = 42 ablation runs, "check" = only build the ablation models, no training.
                   help="run scripts/run_extra.sh <part> instead of one method")  # Text shown by --help.
    p.add_argument("--smoke", action="store_true",  # Flag: do only ONE short run (RTE, 1k, seed 1) to test that the setup works before launching hours of runs.
                   help="only RTE 1k seed 1, to check that everything works")  # Text shown by --help.
    p.add_argument("--no-push", action="store_true",  # Flag: prepare the kernel files and print where they are, but do NOT upload. Useful to inspect what would be sent.
                   help="write the kernel folder and print its path, don't push")  # Text shown by --help.
    args = p.parse_args()  # Read and check the command-line options.
    if not args.method and not args.extra:  # Neither a method nor --extra was given, so there is nothing to run ...
        p.error("give a method or --extra")  # ... print a usage error and exit.

    commit = git("rev-parse", "--short", "HEAD")  # Get the short hash of the current commit, e.g. "bec25ec". It is stored in every result file so results can be traced back to the exact code.
    if git("status", "--porcelain"):  # "git status --porcelain" prints one line per changed file; any output means there are uncommitted changes ...
        commit += "-dirty"  # ... so mark the hash as "-dirty": the uploaded code is NOT exactly that commit, and the results say so honestly.
        print("note: uncommitted changes are uploaded, results get "  # Warn the user about it ...
              f"git_commit={commit}", file=sys.stderr)  # ... on stderr, so the warning stands out.

    files = git("ls-files", "--cached", "--others", "--exclude-standard").splitlines()  # List the files to upload: --cached = files git tracks; --others = new files not yet added; --exclude-standard = but skip anything in .gitignore. This includes finished result JSONs, so those runs are skipped on Kaggle.
    buf = io.BytesIO()  # An empty in-memory "file" to build the archive in (no temporary file on disk).
    with tarfile.open(fileobj=buf, mode="w:gz") as tar:  # Open a new gzip-compressed tar archive that writes into buf. The "with" block closes and finishes the archive automatically at the end.
        for f in files:  # For every listed file ...
            if (REPO / f).is_file():  # ... check it still exists (git can list files that were deleted but not yet committed; adding those would crash) ...
                tar.add(REPO / f, arcname=f)  # ... add it to the archive under its repo-relative path (e.g. src/train.py), so the folder structure is the same when unpacked on Kaggle.
    tarball = buf.getvalue()  # The finished .tar.gz archive as bytes.
    code = base64.b64encode(tarball).decode()  # Convert the bytes to base64 text (only letters, digits, + and /), so it can be placed inside run.py as a normal string.

    if args.extra:  # Mode 1: extra experiments.
        cmds = [f"bash scripts/run_extra.sh {args.extra}"]  # The command to run on Kaggle, e.g. "bash scripts/run_extra.sh ablation".
        slug = f"peft-showdown-extra-{args.extra}"  # The kernel's name on Kaggle (its "slug"), e.g. peft-showdown-extra-ablation.
    elif args.smoke:  # Mode 2: smoke test.
        cmds = [f"python -m src.train --method {args.method} --task rte "  # One short training run (RTE, 1k, seed 1) ...
                f"--regime 1k --seed 1 --overwrite",  # ... with --overwrite, so it runs even if that result already exists.
                "python src/results.py results/final/*.json"]  # Then validate all result files, which should print "ok".
        slug = f"peft-showdown-smoke-{args.method.replace('_', '-')}"  # Kernel name; "_" is replaced by "-" because Kaggle kernel names don't allow underscores.
    else:  # Mode 3 (normal): all 16 final runs of one method.
        cmds = [f"bash scripts/run_method.sh {args.method}"]  # The command that runs all 16 runs one after another.
        slug = f"peft-showdown-{args.method.replace('_', '-')}"  # Kernel name, e.g. peft-showdown-prompt-tuning.

    user = kaggle_username()  # Your Kaggle username, needed for the kernel id.
    out = Path(tempfile.mkdtemp(prefix=f"{slug}_"))  # Create a temporary folder for the two files the Kaggle tool uploads.
    (out / "run.py").write_text(  # Write the script that will run on Kaggle ...
        KERNEL_TEMPLATE.format(code=code, commit=commit, cmds=cmds))  # ... by filling the template's three placeholders with the packed code, the commit hash and the command list.
    (out / "kernel-metadata.json").write_text(json.dumps({  # Write the settings file that the kaggle tool requires next to the script:
        "id": f"{user}/{slug}",  # unique kernel id; pushing the same id again creates a NEW VERSION of the same kernel instead of a new kernel,
        "title": slug,  # title shown on the Kaggle website,
        "code_file": "run.py",  # which file to run,
        "language": "python",  # it is a Python script,
        "kernel_type": "script",  # a plain script (not a notebook),
        "is_private": True,  # only you can see it (the code is private),
        "enable_gpu": True,  # request a GPU; on CPU the 16 runs would take days,
        "enable_internet": True,  # internet is needed for pip install and to download roberta-base and GLUE from Hugging Face,
        "machine_shape": "NvidiaTeslaT4",  # T4 GPU machine. The API only offers T4 x2; src/train.py pins each run to GPU 0 so memory numbers stay correct,
        "dataset_sources": [],  # no Kaggle datasets attached ...
        "competition_sources": [],  # ... no competition data ...
        "kernel_sources": [],  # ... no outputs of other kernels ...
        "model_sources": [],  # ... and no Kaggle models; everything comes from Hugging Face.
    }, indent=2))  # Convert the dict to JSON with 2-space indentation and write it.

    print(f"commit {commit}, {len(tarball) / 1024:.0f} KiB of code -> {out}")  # Summary: which commit is being sent, how big the packed code is (in KiB), and where the kernel files are.
    if args.no_push:  # With --no-push ...
        return  # ... stop here, without uploading; you can inspect the files in the printed folder.
    subprocess.run(["kaggle", "kernels", "push", "-p", str(out)], check=True)  # Upload the folder with the kaggle command-line tool. Kaggle then starts running the script on a GPU, and it keeps running even with your laptop off. check=True raises an error if the upload fails.
    print(f"\nstatus: kaggle kernels status {user}/{slug}\n"  # Print ready-to-copy commands: how to check whether the run is still going ...
          f"output: kaggle kernels output {user}/{slug} -p <dir>\n"  # ... how to download the results when it is done ...
          f"web:    https://www.kaggle.com/code/{user}/{slug}")  # ... and the web link to watch the log in a browser.


if __name__ == "__main__":  # True only when this file is run directly (python scripts/kaggle_push.py ...), not when imported.
    main()  # Start the script.
